package br.com.sussmartcare.notification.infrastructure; import br.com.sussmartcare.notification.application.NotificationChannel; import br.com.sussmartcare.notification.domain.Notification; import org.slf4j.*; import org.springframework.stereotype.Component; @Component public class StaffNotificationChannel implements NotificationChannel {private static final Logger log=LoggerFactory.getLogger(StaffNotificationChannel.class);public boolean supports(String c){return "STAFF_ASSISTED".equalsIgnoreCase(c);}public void send(Notification n){log.info("notification_delivered_simulated adapter=STAFF_ASSISTED patient={} visit={} type={}",n.getPatientId(),n.getVisitId(),n.getType());}}
